contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 newWinnersPerPeriod, uint256 tokenId0, uint256 tokenId1) public payable {
        require(newWinnersPerPeriod == 2, "this test exercises the two-winner selection path");
        require(tokenId0 != tokenId1, "winners must be distinct");

        uint256 roundBefore = c.roundId();
        require(!c.isSelectionComplete(roundBefore), "current round must not already be complete");
        require(address(this) == c._ownerAddress() || c.isAdmin(address(this)), "caller must be able to pick winners");

        c.updateWinnersPerPeriod(newWinnersPerPeriod);
        uint256 winnersPerPeriodAfter = c.winnersPerPeriod();

        uint256 points0 = c.fighterPoints(tokenId0);
        uint256 points1 = c.fighterPoints(tokenId1);
        uint256 totalPointsBefore = c.totalPoints();

        uint256[] memory winners = new uint256[](2);
        winners[0] = tokenId0;
        winners[1] = tokenId1;

        bool reverted;
        try c.pickWinner(winners) { reverted = false; } catch { reverted = true; }

        uint256 roundAfter = c.roundId();
        bool selectionCompleteAfter = c.isSelectionComplete(roundBefore);
        uint256 winner0 = c.fighterPoints(tokenId0);
        uint256 winner1 = c.fighterPoints(tokenId1);
        uint256 totalPointsAfter = c.totalPoints();

        assert(
            winnersPerPeriodAfter == newWinnersPerPeriod &&
            selectionCompleteAfter &&
            (
                (reverted && roundAfter == roundBefore) ||
                (!reverted &&
                 roundAfter == roundBefore + 1 &&
                 winner0 == 0 &&
                 winner1 == 0 &&
                 totalPointsAfter == totalPointsBefore - points0 - points1)
            )
        );
    }
}

