contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenA, uint256 tokenB, uint256 pointsA, uint256 pointsB, uint256 maxId) public payable {
        require(tokenA != tokenB, "distinct tokens");

        c.addPoints(tokenA, pointsA);
        c.addPoints(tokenB, pointsB);

        uint256[] memory points = c.getFighterPoints(maxId);

        uint256 expectedA = (tokenA < maxId) ? pointsA : 0;
        uint256 expectedB = (tokenB < maxId) ? pointsB : 0;

        bool aInRange = tokenA < maxId;
        bool bInRange = tokenB < maxId;

        bool ok = true;
        if (aInRange) {
            ok = ok && (points[tokenA] == expectedA);
        }
        if (bInRange) {
            ok = ok && (points[tokenB] == expectedB);
        }

        assert(ok);
    }

    receive() external payable {}
}

