contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 newWinnersPerPeriod, uint256 fighterA, uint256 fighterB) public payable {
        // Make this test contract an admin so it can perform admin-only setup and calls.
        c.adjustAdminAccess(address(this), true);

        // Set a deterministic winners-per-round count; all subsequent state depends on it.
        c.updateWinnersPerPeriod(newWinnersPerPeriod);

        // Prepare exactly one winner id per slot for the next round.
        uint256[] memory winners = new uint256[](2);
        winners[0] = fighterA;
        winners[1] = fighterB;

        uint256 beforeRoundId = c.roundId();
        address beforeOwnerA = c.ownerOf(fighterA);
        address beforeOwnerB = c.ownerOf(fighterB);

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterRoundId = c.roundId();

        // The first pickWinner call must succeed, advance the round by exactly one,
        // and select exactly the owners of the supplied fighter ids as winners.
        assert(
            !reverted &&
            afterRoundId == beforeRoundId + 1 &&
            c.isSelectionComplete(beforeRoundId) &&
            c.winnerAddresses(beforeRoundId, 0) == beforeOwnerA &&
            c.winnerAddresses(beforeRoundId, 1) == beforeOwnerB
        );
    }
}

