contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint256 newAmount) public {
        require(caller != address(this));
        require(newAmount != c.winnersPerPeriod());

        uint256 before = c.winnersPerPeriod();

        (bool ok, ) = address(c).call(
            abi.encodeWithSignature("updateWinnersPerPeriod(uint256)", newAmount)
        );
        require(!ok);

        assert(c.winnersPerPeriod() == before);
    }

    receive() external payable {}
}

