    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenId) public payable {
        uint256[] memory before = c.getFighterPoints(tokenId);

        bool reverted;
        try c.reRoll(uint8(tokenId), 0) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256[] memory after_ = c.getFighterPoints(tokenId);

        assert(reverted == (before.length == after_.length));
    }

    receive() external payable {}
}

