contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 token0, uint256 token1, uint256 newWinnersPerPeriod) public {
        require(newWinnersPerPeriod == 2);

        uint256 roundBefore = c.roundId();
        require(!c.isSelectionComplete(roundBefore));

        c.updateWinnersPerPeriod(newWinnersPerPeriod);

        uint256[] memory winners = new uint256[](2);
        winners[0] = token0;
        winners[1] = token1;

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(
                c.isSelectionComplete(roundBefore) &&
                c.roundId() == roundBefore + 1 &&
                c.winnerAddresses(roundBefore, 0) != address(0) &&
                c.winnerAddresses(roundBefore, 1) != address(0) &&
                c.winnerAddresses(roundBefore, 0) == c.winnerAddresses(roundBefore, 0) &&
                c.winnerAddresses(roundBefore, 1) == c.winnerAddresses(roundBefore, 1) &&
                c.winnerAddresses(roundBefore, 0) != c.winnerAddresses(roundBefore, 1) || token0 == token1
            );
        }
    }
}

