contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 points, uint256 tokenId) public {
        require(tokenId > 0 && points > 0, "invalid input");

        // Read initial state via public getters.
        uint256 initialTotalPoints = c.totalPoints();

        // Try to call admin functions from zero address (not admin).
        bool revertedPickWinner = false;
        try c.pickWinner(new uint256[](0)) {
            revertedPickWinner = false;
        } catch {
            revertedPickWinner = true;
        }

        bool revertedUpdateWinners = false;
        try c.updateWinnersPerPeriod(winnersPerPeriod) {
            revertedUpdateWinners = false;
        } catch {
            revertedUpdateWinners = true;
        }

        bool revertedAdjustAdmin = false;
        try c.adjustAdminAccess(address(0), true) {
            revertedAdjustAdmin = false;
        } catch {
            revertedAdjustAdmin = true;
        }

        // Read final state.
        uint256 finalTotalPoints = c.totalPoints();

        // Assert the general rule: from a non-admin caller, no changes occur and admin calls revert.
        assert(
            (revertedPickWinner && revertedUpdateWinners && revertedAdjustAdmin) ||
            (finalTotalPoints == initialTotalPoints)
        );
    }
}

