contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 tokenIdWin,
        uint256 tokenIdOther,
        uint256 pointsWin,
        uint256 pointsOther
    ) public payable {
        require(tokenIdWin != tokenIdOther, "token ids must differ");
        require(pointsWin <= 10**30, "points too large");
        require(pointsOther <= 10**30, "points too large");

        // Make sure the owner has admin rights.
        c.adjustAdminAccess(address(this), true);

        // Ensure the chosen winners-per-period amount is 2 so pickWinner's length check passes.
        c.updateWinnersPerPeriod(2);

        // Add points to the two fighters.
        c.addPoints(tokenIdWin, pointsWin);
        c.addPoints(tokenIdOther, pointsOther);

        // Record the total points before the winner is picked.
        uint256 beforeTotal = c.totalPoints();

        uint256[] memory winners = new uint256[](2);
        winners[0] = tokenIdWin;
        winners[1] = tokenIdOther;
        c.pickWinner(winners);

        // After pickWinner, total points should have decreased by the sum of the chosen fighters' points.
        uint256 expectedAfterTotal = beforeTotal - pointsWin - pointsOther;
        require(c.totalPoints() == expectedAfterTotal, "total points mismatch after pickWinner");

        // The two chosen fighters must have zero points now.
        require(c.fighterPoints(tokenIdWin) == 0, "winner points not cleared");
        require(c.fighterPoints(tokenIdOther) == 0, "winner points not cleared");

        // For this test, stop here.  The important invariant is the points bookkeeping above.
        assert(c.totalPoints() == expectedAfterTotal && c.fighterPoints(tokenIdWin) == 0 && c.fighterPoints(tokenIdOther) == 0);
    }
}

