        // Make c the state the rule needs: caller is the InvMutTest contract
        // (msg.sender), which is not necessarily an admin.
        // Try to change winnersPerPeriod; must revert for non-admins.
        bool reverted;
        try c.updateWinnersPerPeriod(newAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterVal = c.winnersPerPeriod();

        // General rule: unless the caller is known to be allowed to go through
        // (we cannot know here), if it reverted the value must be unchanged.
        // If it did NOT revert, the value was accepted.
        if (reverted) {
            assert(afterVal == beforeVal);
        } else {
            assert(afterVal == newAmount);
        }
    }
}

