contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 roundCount) public {
        require(roundCount > 0 && roundCount <= 4, "roundCount out of range");

        uint256 roundIdBefore = c.roundId();
        uint32 claimedBefore = c.numRoundsClaimed(address(this));

        uint256 roundsToProcess;
        if (roundIdBefore > claimedBefore) {
            roundsToProcess = roundIdBefore - claimedBefore;
        } else {
            roundsToProcess = 0;
        }

        string[] memory modelURIs = new string[](roundsToProcess);
        string[] memory modelTypes = new string[](roundsToProcess);
        uint256[2][] memory customAttributes = new uint256[2][](roundsToProcess);

        uint256 claimedRewardCount = 0;
        for (uint256 r = claimedBefore; r < roundIdBefore; r++) {
            uint256 len = c.winnerAddresses(r).length;
            for (uint256 j = 0; j < len; j++) {
                if (c.winnerAddresses(r)[j] == address(this)) {
                    claimedRewardCount++;
                }
            }
        }

        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint32 claimedAfter = c.numRoundsClaimed(address(this));

        assert(!reverted && claimedAfter == claimedBefore + roundsToProcess);
    }

    receive() external payable {}
}

